import type { Scenario, Scene } from '../types';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

type KitOption = { id: string; label: string; consequence: string };
type ResponseOption = { id: string; label: string; consequence: string };
type Followup = { title: string; text: string; choices: [{ id: string; label: string; consequence: string }, { id: string; label: string; consequence: string }] };
type Card = {
  id: string; title: string; subtitle: string; hook: string; role: string; activity: string; setting: string;
  risk: 'LOW' | 'MODERATE' | 'HIGH' | 'SEVERE'; startTitle: string; start: string;
  kit: [KitOption, KitOption, KitOption]; turnTitle: string; turn: string;
  responses: [ResponseOption, ResponseOption, ResponseOption]; settlement: string;
  gear: string; gearName: string; gearSource: string; coins: number; knowledge: string;
  combat?: { enemy: string; winChance: number; damageOnLoss: number; winText: string; lossText: string };
  lore?: string;
};

const scene = (id: string, title: string, text: string, choices: Scene['choices'], tone: Scene['tone'] = 'safe', textVariants?: Scene['textVariants']): Scene => ({ id, title, text, choices, ...(tone !== 'safe' ? { tone } : {}), ...(textVariants ? { textVariants } : {}) });
const end = (id: string, title: string, text: string) => largeEnd(id, title, text);

const followups: Record<string, Followup> = {
  'glass-road': { title: 'The Marker Has Moved', text: 'The assistant returns with one more detail: the boundary post was lifted from its socket, but the wagon ruts are too old to date the change. Rook asks what should be recorded before the county crew arrives.', choices: [{ id: 'recordEvidence', label: 'Record the post, tracks, and their limits separately', consequence: 'The report preserves what was seen without naming a culprit.' }, { id: 'leaveSite', label: 'Stop searching and leave the post undisturbed', consequence: 'The site stays intact for the county crew, while the missing time remains unexplained.' }] },
  'chain-of-sight': { title: 'A Gate Opens onto the Line', text: 'The neighbor brings an older deed sketch. It supports the straight line but cannot establish whether the gate was moved with permission. Bell asks how to mark the map until the clerk reviews it.', choices: [{ id: 'labelProvisional', label: 'Mark the line provisional and attach both measurements', consequence: 'The map is useful to the crews without pretending to settle ownership.' }, { id: 'holdStakes', label: 'Hold the stakes until the clerk checks the deed', consequence: 'No one builds across the disputed strip while the records are checked.' }] },
  'three-points-down': { title: 'A Second Sound from the Fissure', text: 'As Vale prepares to leave, pebbles fall from the fissure. The tin is still visible, but the entrance has changed since the first inspection. You must decide what to leave for the next party.', choices: [{ id: 'markFissure', label: 'Mark the altered entrance and leave the tin', consequence: 'The next guide gets a clear warning and a record of the change.' }, { id: 'closeCave', label: 'Ask the landowner to close the cave until inspection', consequence: 'The owner receives a specific reason to keep visitors out.' }] },
  'the-mule-load': { title: 'A Second Animal Refuses', text: 'A second mule balks at the same bend, even after the first load is removed. Noll finds a loose strip of harness leather snagging its flank; the frame was not the only problem.', choices: [{ id: 'restAnimals', label: 'Rest both animals and inspect every harness', consequence: 'Departure is delayed, but a second rub is found before it becomes an injury.' }, { id: 'moveCargo', label: 'Transfer the awkward cargo to the wagon', consequence: 'The caravan travels slower, with both animals relieved of the suspect loads.' }] },
  'the-unseated-winch': { title: 'The Owner Arrives with the Salvage Papers', text: 'The barge owner arrives while the deckhand is being helped ashore. The papers authorize recovery of the hull, but not removal of its fittings. Dey asks you to separate crew property from vessel property.', choices: [{ id: 'inventoryCrewKit', label: 'Inventory the duplicated crew kit with the owner', consequence: 'Only the crew’s separately owned spare can transfer; the barge hardware stays aboard.' }, { id: 'deferTransfer', label: 'Wait for the owner to inspect each fitting', consequence: 'The salvage pauses, and no disputed equipment changes hands.' }] },
  'the-iron-claim': { title: 'The Clerk Finds a Date', text: 'The claim clerk finds an old work order naming a public-works Hand Auger, but its serial mark is obscured. The tool in the cut remains in custody while a separate fee is authorized.', choices: [{ id: 'keepCustody', label: 'Leave the disputed auger sealed until identification', consequence: 'Neither crew can alter the evidence before the mark is checked.' }, { id: 'signSeparateFee', label: 'Sign only for the clerk’s separate fee tool', consequence: 'The public-works spare transfers on paper; the disputed auger stays with the clerk.' }] },
  'the-storm-marker': { title: 'The Hiker Knows the Old Route', text: 'At the ridge, the hiker recognizes a washed-out side path from last year. It once reached the creek footbridge, but today the far bank is cut away. Familiarity cannot make that crossing safe.', choices: [{ id: 'keepHighDetour', label: 'Keep the hiker on the marked high detour', consequence: 'The longer route stays open while the crew closes the washed-out approach.' }, { id: 'waitSecondCrew', label: 'Wait for a second crew before reopening any trail', consequence: 'The route stays closed until both approaches are checked.' }] },
  'the-second-gunhand': { title: 'The Toll Patrol Takes Statements', text: 'Once the road is clear, the patrol asks whether the cut cord was already there or placed to stop the wagon. No one saw the men arrive, and the road holds no clear boot trail.', choices: [{ id: 'reportObserved', label: 'Report only what you saw and heard', consequence: 'The patrol records the armed demand without claiming who laid the cord.' }, { id: 'closeRoad', label: 'Keep the wagon at the toll station until daylight', consequence: 'The payroll stays secure, though the next delivery is delayed.' }] },
};

/* Editorial planning is encoded per card: each has a distinct specialist, setting, equipment
   tradeoff, complication, response, and explicit ownership transfer. Shared scene plumbing
   keeps IDs and reward handling consistent; it does not supply story outcomes. */
function build(c: Card): Scenario {
  const followup = followups[c.id];
  const tags = largeTags({
    hook: c.hook, role: /investigation|mystery/.test(c.activity) ? 'investigator/explorer' : /rescue|animal/.test(c.activity) ? 'helper/rescuer' : /labor|combat/.test(c.activity) ? 'worker' : 'traveler/passenger', activity: c.activity, tone: c.risk === 'LOW' ? 'adventurous' : 'tense/dangerous',
    risk: c.risk, setting: c.setting, fantasy: 'NONE', combat: c.combat ? 'POSSIBLE' : 'NONE',
    structures: ['equipment allocation', 'support role becomes independent action', 'performance payoff'],
    entry: ['hired/posted work'], rewards: ['Gear', 'coins', 'reusable Knowledge', ...(c.lore ? ['Lore'] : [])],
    outcomes: ['success/partial success', 'walk-away/refusal', 'costly success/no-perfect-outcome possible'],
  });
  const options = c.kit.map((o) => ({ id: `kit_${o.id}`, label: o.label, next: 'complication', effects: { setFlags: [`support_kit_${o.id}`] } }));
  const variants = c.kit.map((o) => ({ requirements: { flags: [`support_kit_${o.id}`] }, text: o.consequence }));
  const responses: Scene['choices'] = [
    ...c.responses.map((o) => ({ id: `response_${o.id}`, label: o.label, next: followup ? 'followup' : 'settlement', effects: { setFlags: [`support_response_${o.id}`] } })),
    ...(c.combat ? [{ id: 'standGround', label: `Hold the line and fight the ${c.combat.enemy}`, hint: 'The other person can retreat while you keep the route open.', effects: { combat: { enemy: c.combat.enemy, winChance: c.combat.winChance, damageOnLoss: c.combat.damageOnLoss, damageOnWin: 1, winNext: 'afterFight', lossNext: 'retreat' } } }] : []),
  ];
  const settlementVariants = followup
    ? c.responses.flatMap((response) => followup.choices.map((choice) => ({ requirements: { flags: [`support_response_${response.id}`, `support_followup_${choice.id}`] }, text: `${response.consequence} ${choice.consequence} ${c.settlement}` })))
    : c.responses.map((o) => ({ requirements: { flags: [`support_response_${o.id}`] }, text: o.consequence }));
  const scenes: Record<string, Scene> = {
    preparation: scene('preparation', c.startTitle, c.start, options),
    complication: scene('complication', c.turnTitle, c.turn, responses, c.risk === 'HIGH' || c.risk === 'SEVERE' ? 'warning' : 'safe', variants),
    ...(followup ? { followup: scene('followup', followup.title, followup.text, followup.choices.map((choice) => ({ id: `followup_${choice.id}`, label: choice.label, next: 'settlement', effects: { setFlags: [`support_followup_${choice.id}`] } })), c.risk === 'HIGH' || c.risk === 'SEVERE' ? 'warning' : 'safe', c.responses.map((response) => ({ requirements: { flags: [`support_response_${response.id}`] }, text: `${response.consequence} ${followup.text}` }))) } : {}),
    settlement: scene('settlement', 'What the Work Was Worth', c.settlement, [
      { id: 'acceptGear', label: `Accept ${c.gearName} as the agreed hand-off`, requirements: { notOwnedItems: [c.gear] }, next: 'gear', effects: { gainItems: [c.gear], historyFlags: [`earned_${c.id}_gear`] } },
      { id: 'takeCoins', label: `Take ${c.coins} coins instead`, next: 'paid', effects: { money: c.coins } },
      { id: 'keepKnowledge', label: 'Decline payment and keep the practical lesson', next: 'lesson', effects: { knowledge: [c.knowledge] } },
      { id: 'declineAll', label: 'Thank them and leave without payment', next: 'unpaid' },
    ], 'safe', settlementVariants),
    gear: end('gear', 'A Tool with a New Owner', c.gearSource),
    paid: end('paid', 'Paid for the Work', `You accept ${c.coins} coins, not the ${c.gearName}. The equipment remains with its owner, and the work is finished without any second payment.`),
    lesson: end('lesson', 'A Lesson Kept', `You leave without coins or ${c.gearName}. ${c.knowledge}`),
    unpaid: end('unpaid', 'The Road Opens Again', 'You refuse compensation. The specialist records what the work taught them, but no equipment changes hands.'),
  };
  if (c.combat) {
    scenes.afterFight = scene('afterFight', 'The Route Holds', c.combat.winText, [{ id: 'continueAfterFight', label: 'Check the other person and finish the work', next: followup ? 'followup' : 'settlement' }], 'warning');
    scenes.retreat = end('retreat', 'A Hard Withdrawal', c.combat.lossText);
  }
  const endings = Object.entries(scenes).filter(([, value]) => value.ending).map(([id]) => id);
  const storyScenes = Object.fromEntries(Object.entries(scenes).map(([id, value]) => [id, id === 'gear' ? { ...value, text: `${value.text} ${c.lore ? `You also hear the old account: ${c.lore}` : ''}` } : value]));
  return largeAdventure(c.id, c.title, c.subtitle, tags, 'preparation', storyScenes);
}

const cards: Card[] = [
  { id:'glass-road', title:'The Glass Road', subtitle:'A naturalist hires a second pair of eyes for a day in open country.', hook:'A naturalist and traveler distinguish a distant herd from movement near an abandoned signal post.', role:'naturalist assistant', activity:'travel/exploration', setting:'open prairie and signal post', risk:'LOW', startTitle:'A Shape Beyond the Grass', start:'Dr. Ilyan Rook is tracking pronghorn for a county survey, not hunting them. A second movement flickers near an empty signal post. His Field Glasses, your Trail Compass, and his red cloth markers cannot all be used at once while one person keeps the notebook.', kit:[{id:'glasses',label:'Take the Field Glasses and watch the post',consequence:'The glasses resolve a moving coat sleeve on the post, not an animal. Rook stays with the notebook while you decide how to approach.'},{id:'compass',label:'Keep the Trail Compass for the return line',consequence:'You mark a reliable bearing before the grass closes the view; the distant movement remains uncertain.'},{id:'flags',label:'Take the red markers to signal from the rise',consequence:'Your flag gives Rook a visible point to walk toward, though it cannot identify what moved.'}], turnTitle:'Not Every Shape Is Wildlife', turn:'At the post, the movement stops. A survey assistant’s coat hangs from a nail; the person is nowhere in sight, and the tracks below have been crossed by wagon ruts.', responses:[{id:'call',label:'Call out and wait in the open',consequence:'A delayed answer comes from beyond the rise; the assistant was checking a collapsed marker and is unhurt.'},{id:'circle',label:'Circle wide and keep the return bearing',consequence:'You find the assistant’s boot prints leaving the post by the eastern slope; the compass keeps the search from widening.'},{id:'signal',label:'Signal Rook to approach before moving closer',consequence:'Rook reaches you without losing sight of the post, and the two of you hear the assistant answer from the far side.'}], settlement:'The assistant was sent to check an old boundary marker and apologizes for causing a false alarm. Rook offers his spare Field Glasses or the agreed day fee.', gear:'fieldGlasses',gearName:'Field Glasses',gearSource:'Rook signs over a spare pair from the survey chest; the lenses are clear, and their previous owner has already been paid.',coins:2,knowledge:'Movement at distance is easier to identify when a fixed landmark remains in view; magnification cannot make an obscured figure certain.', lore:'The signal post once marked the end of a cattle trail before the rail spur crossed it.' },
  { id:'saw-before-sunrise', title:'Saw Before Sunrise', subtitle:'A mountain guide needs a clear path, but the shortest cut is not the safest.', hook:'A guide and assistant choose how to clear a blocked pass without releasing a hanging limb.', role:'mountain guide assistant', activity:'survival', setting:'wooded mountain pass', risk:'MODERATE', startTitle:'The Pass Is Not Empty', start:'Guide Sella Marr has a folding brush saw, a hand axe, and a short rope. A storm has dropped green limbs across the marked pass; one larger branch hangs above the path. You are asked to choose the first tool while she checks the slope.', kit:[{id:'saw',label:'Use the Folding Brush Saw on the smaller limbs',consequence:'The saw clears brush quietly and leaves the hanging branch untouched; a narrow footpath appears along the rock.'},{id:'axe',label:'Use the hand axe to open the direct line',consequence:'The axe cuts faster through thick brush but sends a sharp crack uphill; gravel starts ticking down the slope.'},{id:'rope',label:'Set the rope around the sound trunk first',consequence:'The line gives Marr a way to steady the hanging limb, but tying it delays opening the narrow path.'}], turnTitle:'A Limb Under Tension', turn:'The large branch is caught between two trunks, flexed toward the only level stretch of trail. A pack mule is heard beyond it, but no handler answers the first call.', responses:[{id:'cutSmall',label:'Clear a side path and call the handler back',consequence:'The mule handler reaches the pass from the lower track; no one needs to disturb the trapped limb.'},{id:'secure',label:'Have Marr secure the branch while you guide the mule',consequence:'The branch shifts once against the line, then holds while the mule is led around the rock side.'},{id:'wait',label:'Wait for the handler before moving anything',consequence:'The handler appears with a second mule and confirms the animal is calm; the delay prevents a blind approach.'}], settlement:'Marr’s saw has lost a tooth but still cuts brush. The guide owns a sound spare and offers it as your share of the work or two coins.', gear:'foldingBrushSaw',gearName:'Folding Brush Saw',gearSource:'Marr gives you her separately owned spare saw; the damaged one stays with her for repair.',coins:2,knowledge:'A branch held under tension can spring toward the cut; clear an alternate route before cutting it.', lore:'Marr’s first guide marked this pass by the shape of a split cedar.' },
  { id:'chain-of-sight', title:'A Chain of Sight', subtitle:'Two surveyors disagree about the line of an old boundary.', hook:'A survey assistant checks whether a washed-out boundary follows the old line or the current road.', role:'survey assistant', activity:'investigation/mystery', setting:'county boundary and stone culvert', risk:'LOW', startTitle:'The Line on the Map', start:'Surveyor Bell and road foreman Hask disagree by nearly a field’s width. Bell has a Survey Chain; Hask trusts the old folding rule and a stone culvert. You must decide what to measure before either man stakes the new line.', kit:[{id:'chain',label:'Stretch the Survey Chain between the old stones',consequence:'The chain spans the ground the map calls the boundary, but one stone is visibly reset.'},{id:'rule',label:'Check the culvert with the folding rule',consequence:'The rule shows the culvert stone was replaced; that local measurement cannot settle the longer boundary.'},{id:'stakes',label:'Set temporary flags along the traveled road',consequence:'The flags record where wagons actually go, not where the property line legally lies.'}], turnTitle:'A Boundary Has Two Histories', turn:'A farm gate and a new wheel rut complicate the measurement: the traveled road bends around the culvert, while the old map follows the straight line.', responses:[{id:'compare',label:'Measure both lines and label them separately',consequence:'Bell and Hask accept a map showing the old boundary and the current wagon route as separate facts.'},{id:'witness',label:'Ask the neighboring farmer where the old gate stood',consequence:'The farmer points out a hinge scar on the original post; it supports the old line without proving ownership by itself.'},{id:'defer',label:'Post temporary markers and request a second survey',consequence:'No boundary is declared today, but the temporary markers prevent the crew from building across either disputed line.'}], settlement:'Bell has no apprentice and is retiring from field work. The Survey Chain is his own spare, offered as a hand-off; he can instead pay the agreed fee.', gear:'surveyChain',gearName:'Survey Chain',gearSource:'Bell records the chain as transferred from his personal kit; Hask keeps the county’s measuring equipment.',coins:3,knowledge:'When a road and a property boundary diverge, measure and label both rather than treating the traveled route as proof of title.', lore:'The boundary stones predate the present road by two generations.' },
  { id:'three-points-down', title:'Three Points Down', subtitle:'A cave guide asks you to anchor a return line above a new fissure.', hook:'A cave explorer must recover a dropped survey tin without placing anchors in cracked rock.', role:'cave explorer assistant', activity:'travel/exploration', setting:'limestone cave entrance', risk:'HIGH', startTitle:'A Line Is Not an Anchor', start:'Nera Vale is a careful cave guide, but a new fissure has opened beside the entrance. Her climbing pitons, your Travel Rope, and a wooden brace offer different ways to keep a return line visible. None makes the cracked lip safe.', kit:[{id:'pitons',label:'Inspect sound rock for a removable piton anchor',consequence:'You find solid stone beyond the fissure; a piton can hold a short return line if the guide tests it first.'},{id:'rope',label:'Keep the rope on the surface and mark a retreat',consequence:'The rope remains available for withdrawal rather than descent; the dropped survey tin stays below.'},{id:'brace',label:'Set the wooden brace across the approach',consequence:'The brace warns the next person away from the lip but cannot bear a climber’s weight.'}], turnTitle:'The Tin Is Below the Crack', turn:'The survey tin lies on a shelf under the split. Vale can see it, but a pebble falls from the fissure while she considers lowering herself.', responses:[{id:'leave',label:'Leave the tin and document the changed entrance',consequence:'Vale sketches the fissure and closes the route until a second guide can inspect it.'},{id:'line',label:'Use a tested line from sound rock for a short reach',consequence:'The line supports a controlled reach from the firm side; the tin comes up, but no one enters the fissure.'},{id:'return',label:'Withdraw and ask the landowner to close the cave',consequence:'You both leave by the marked path and give the landowner a clear reason to close the entrance.'}], settlement:'Vale offers a spare set of climbing pitons from her personal kit, with instructions to use them only in sound rock; she can pay three coins instead.', gear:'climbingPitons',gearName:'Climbing Pitons',gearSource:'Vale transfers her spare removable anchors to you. The inspected piton remains in place only until the landowner can safely remove it.',coins:3,knowledge:'An anchor is only as sound as the rock around it; a rope cannot make fractured stone trustworthy.', lore:'Vale has closed this cave once before after a winter freeze shifted the entrance.' },
  { id:'the-mule-load', title:'The Mule Load', subtitle:'A packer’s frame is missing, and the train leaves at noon.', hook:'A caravan packer allocates carrying gear after one mule refuses a familiar load.', role:'caravan packer assistant', activity:'animals', setting:'railhead wagon camp', risk:'LOW', startTitle:'A Load Out of Balance', start:'Packer Noll has one freight strap, a pack frame, and a waxed canvas sheet. A mule balks when a tin box shifts against its flank; the rest of the caravan is ready to depart.', kit:[{id:'frame',label:'Move the box to the Pack Frame',consequence:'The frame keeps the box clear of the animal’s ribs, but leaves the feed sack without a carrier.'},{id:'strap',label:'Secure the box with the Freightman’s Strap',consequence:'The strap stops the box sliding, though its weight still presses close to the mule.'},{id:'sheet',label:'Wrap the box in the waxed canvas',consequence:'The canvas silences the rattling metal; it does not fix the load’s balance.'}], turnTitle:'The Mule Has a Reason', turn:'The mule takes two steps, then pins its ears at the box’s sharp corner. Noll finds a rubbed patch beneath the pack; the animal is not being stubborn without cause.', responses:[{id:'redistribute',label:'Unload and divide the weight between two animals',consequence:'The caravan loses time but the mule settles after the pressure is removed.'},{id:'lead',label:'Walk the mule unloaded while Noll checks its back',consequence:'A tender patch is found before the animal is asked to carry another mile.'},{id:'reroute',label:'Send the box by wagon and keep the mule with the group',consequence:'The wagon takes the awkward cargo, and the mule travels without the rubbing pack.'}], settlement:'Noll has a spare Pack Frame he bought for a larger animal and offers it to you rather than carry it back unused.', gear:'packFrame',gearName:'Pack Frame',gearSource:'Noll gives you the unused frame; the caravan retains its fitted frames and the mule’s load is corrected first.',coins:1,knowledge:'A shifting load can injure an animal even when the straps stay tight; check pressure points before departure.', lore:'Noll’s pack marks are copied from a freight team that crossed the northern pass.' },
  { id:'pilot-hole', title:'The Pilot Hole', subtitle:'A bridge carpenter needs help without splitting a brace that carries real weight.', hook:'A carpenter chooses between forcing a fastener and boring a careful pilot hole in old timber.', role:'carpenter assistant', activity:'labor/repair', setting:'timber footbridge repair yard', risk:'MODERATE', startTitle:'Old Wood, New Brace', start:'Carpenter Jory Fen has a Hand Auger, a Bridgewright’s Hammer, and a steel wedge. The replacement brace must fit before wagons return tomorrow; the old beam is dry and split-prone.', kit:[{id:'auger',label:'Bore a narrow pilot hole with the Hand Auger',consequence:'The auger turns cleanly through the sound edge, though you must measure twice before moving the brace.'},{id:'hammer',label:'Test the fit with the Bridgewright’s Hammer',consequence:'The hammer seats the test peg but cannot tell whether the beam will split under a longer fastener.'},{id:'wedge',label:'Lift the brace slightly with the Steel Wedge',consequence:'The wedge buys room to align the brace; the carpenter still needs a safe fastening plan.'}], turnTitle:'A Crack Beneath the Paint', turn:'Fen scrapes away a strip of paint and finds a hairline crack at the old fastening. The bridge remains closed; no one is asked to test it with a wagon.', responses:[{id:'bore',label:'Bore a pilot hole in the new brace and test the grain',consequence:'The test hole stays within sound timber, and the new brace seats without extending the old crack.'},{id:'replace',label:'Reject the old beam and cut a replacement',consequence:'The work takes longer, but the damaged beam is not trusted to carry traffic.'},{id:'inspect',label:'Ask the crew lead to inspect both supports before fitting',consequence:'The lead finds a second worn fastening and expands the repair rather than hiding it.'}], settlement:'Fen has a personally owned spare Hand Auger from his apprentice days and offers it after you finish the careful repair.', gear:'handAuger',gearName:'Hand Auger',gearSource:'Fen gives you his own spare auger after the bridge crew signs the repaired span closed pending inspection.',coins:3,knowledge:'A pilot hole reduces splitting risk in dry timber, but it cannot make a cracked load-bearing beam sound.', lore:'Fen’s old shop mark is filed into the auger’s wooden handle.' },
  { id:'daylight-flags', title:'Flags at the Cut', subtitle:'A courier’s route bends beyond sight of the station.', hook:'A courier team sets a daylight signal system across a rail cut where whistles carry poorly.', role:'courier assistant', activity:'communication/witness', setting:'rail cut and wayside station', risk:'MODERATE', startTitle:'A Message Around the Bend', start:'Courier Ada Pike must guide a wagon across a rail cut while a station clerk watches the far crossing. Signal flags, a Conductor’s Whistle, and a mirror each work differently in clear daylight.', kit:[{id:'flags',label:'Lay out the Signal Flag Set',consequence:'The red and white flags are visible around the bend when held above the bank, but only to someone looking toward the cut.'},{id:'whistle',label:'Use the Conductor’s Whistle for the first signal',consequence:'The whistle carries over the rails but echoes from the cut; the clerk cannot tell which direction to look.'},{id:'mirror',label:'Use the Roadside Signal Mirror from the rise',consequence:'A reflected flash reaches the station window, though cloud cover is moving in.'}], turnTitle:'The Clerk Looks the Wrong Way', turn:'The clerk answers from the platform, not the crossing. A freight train is expected later, and the wagon cannot be left on the rail approach while you correct the signal.', responses:[{id:'flags',label:'Hold the flags where the clerk can see the full pattern',consequence:'The clerk repeats the agreed red-white-red pattern from the safe side of the cut.'},{id:'runner',label:'Send the courier on foot to confirm the message',consequence:'The courier reaches the station without placing the wagon on the rails; the delay is clear and controlled.'},{id:'wait',label:'Wait until the clerk takes the marked lookout post',consequence:'The clerk moves to the posted position, and the next flag signal is understood.'}], settlement:'Pike bought an extra pair of flags for the next route and offers them to you as your agreed field kit.', gear:'signalFlagSet',gearName:'Signal Flag Set',gearSource:'Pike signs over the spare pair. They are a daylight signaling aid, not a substitute for posted rail procedure.',coins:2,knowledge:'A signal only works when sender and receiver share both the pattern and the place to watch.', lore:'The cut’s old semaphore post was removed when the station moved uphill.' },
  { id:'the-unseated-winch', title:'The Unseated Winch', subtitle:'A salvage captain wants a machine moved without trusting its corroded frame.', hook:'A salvage assistant stabilizes an old hand winch before a loaded skiff drifts into a piling.', role:'salvage assistant', activity:'rescue/care', setting:'river wharf and derelict barge', risk:'HIGH', startTitle:'A Winch with No Footing', start:'Captain Orla Dey is salvaging a derelict barge with written permission from its owner. Her block-and-tackle, your rope clamp, and a hand winch are available. The winch bolts are rusted into a plank that flexes under load.', kit:[{id:'tackle',label:'Rig the Compact Block-and-Tackle to a sound piling',consequence:'The pulley gives leverage from a stable point, though the lift will be slow and needs a second line.'},{id:'clamp',label:'Secure the wet line with the Iron Rope Clamp',consequence:'The clamp holds the line without relying on a wet knot; it does not strengthen the winch plank.'},{id:'winch',label:'Test the hand winch with no load',consequence:'The drum turns, but the plank bows before any cargo is attached.'}], turnTitle:'The Barge Begins to Swing', turn:'The river current shifts the barge toward a piling. A deckhand is still aboard, and the old winch cannot safely hold the hull.', responses:[{id:'haul',label:'Use the sound piling as a slow hauling point',consequence:'The barge swings clear by inches; the deckhand steps to the wharf before the salvage resumes.'},{id:'release',label:'Cut the temporary line and let the hull settle against fenders',consequence:'The salvage pauses, but the barge rests against padded fenders instead of tearing the old plank free.'},{id:'board',label:'Call the deckhand ashore before moving the hull',consequence:'The deckhand leaves by the gangplank; the crew secures the barge only after everyone is clear.'}], settlement:'Dey offers you a spare Compact Block-and-Tackle from her private locker after the owner confirms the salvage crew may keep its own duplicated kit.', gear:'compactBlockAndTackle',gearName:'Compact Block-and-Tackle',gearSource:'Dey transfers her personal spare after the permitted salvage is completed; the owner’s barge fittings remain aboard.',coins:3,knowledge:'A pulley redirects effort but cannot strengthen the surface or structure carrying its anchor.', combat:{enemy:'barge thieves',winChance:.58,damageOnLoss:4,winText:'The thieves retreat when the crew rallies around the wharf bell. One drops a lantern, but the owner claims it; nothing is taken as loot.',lossText:'You take a hard blow while holding the wharf. Dey gets the deckhand clear and the thieves escape with a coil of the owner’s line.'} },
  { id:'the-silent-hound', title:'The Silent Hound', subtitle:'A tracker’s dog has stopped following a trail and will not cross a dry wash.', hook:'A tracker and assistant learn whether a hound has found danger or simply lost the scent in a dry wash.', role:'tracker assistant', activity:'animals', setting:'dry wash and scrub country', risk:'MODERATE', startTitle:'A Dog That Will Not Advance', start:'Tracker Mace Orro’s hound stops at a dry wash. Orro has field glasses; you have a Trail Whistle and a spare lead. The dog is not in immediate danger, but its refusal means something changed.', kit:[{id:'glasses',label:'Watch the opposite bank through Field Glasses',consequence:'A strip of fresh cloth hangs on a thorn across the wash; no person is visible.'},{id:'whistle',label:'Use the Trail Whistle once from firm ground',consequence:'The hound looks back but does not cross; the sound has not reassured it.'},{id:'lead',label:'Take the spare lead and approach the near edge',consequence:'The lead gives Orro control if the dog turns, while you stay on the bank.'}], turnTitle:'The Scent Ends at Water', turn:'The wash carries a narrow trickle beneath dry sand. The trail ends where the water crosses, and a set of human boot prints turns uphill.', responses:[{id:'follow',label:'Follow the boot prints uphill with Orro',consequence:'You find a lost survey hand sitting in shade. The dog had stopped at the water because the scent ended there.'},{id:'water',label:'Let the hound drink before continuing',consequence:'The animal drinks and resumes only when Orro offers the uphill scent, not the vanished trail.'},{id:'withdraw',label:'Mark the wash and report the missing scent',consequence:'Orro leaves a clear mark for the search party instead of forcing the hound across uncertain ground.'}], settlement:'Orro’s spare field glasses are sound and personally owned; he offers them or the agreed two-coin fee.', gear:'fieldGlasses',gearName:'Field Glasses',gearSource:'Orro transfers his privately owned spare glasses after the missing hand is found and the hound is watered.',coins:2,knowledge:'A trail can end at flowing water without the traveler being lost; a trained animal’s hesitation is information, not proof of a threat.',lore:'Orro learned to track by watching how working dogs stop at a change in scent.' },
  { id:'the-iron-claim', title:'The Iron Claim', subtitle:'Two prospectors want help recovering a tool from a disputed cut.', hook:'A claim dispute escalates when a tool is found in a cut that both crews say they own.', role:'neutral support hand', activity:'negotiation/trade', setting:'abandoned mining cut', risk:'HIGH', startTitle:'A Tool in the Cut', start:'Prospectors Bale and Morrow argue over a hand auger found beside a collapsed claim marker. Neither can prove who brought it there. You are hired to keep the recovery orderly, not to decide the title.', kit:[{id:'chain',label:'Measure the cut from the last recorded marker',consequence:'The Survey Chain places the auger outside both crews’ marked working faces, but not outside the broader claim.'},{id:'flags',label:'Mark a no-entry line until the owners meet',consequence:'The Signal Flags make the temporary boundary visible; both crews can still dispute its legal meaning.'},{id:'glasses',label:'Watch both crews from the safe ridge',consequence:'Field Glasses show neither crew has entered the cut yet; the argument remains verbal.'}], turnTitle:'A Claim Is Not a Receipt', turn:'A younger worker slips toward the auger while the two prospectors shout. Loose shale shifts near the cut’s lip.', responses:[{id:'callBack',label:'Call the worker back and ask both owners to witness recovery',consequence:'The worker steps away; Bale and Morrow agree to record the tool’s location before moving it.'},{id:'barrier',label:'Close the cut with flags and a timber barrier',consequence:'The barrier prevents a rushed recovery until the claim clerk can check the boundary.'},{id:'mediate',label:'Offer to carry the auger to the clerk under both signatures',consequence:'Both crews sign the receipt; the tool goes to the claim clerk, not into your pack.'}], settlement:'The clerk later awards you a spare Hand Auger from the public works chest for keeping the recovery neutral; it is not the disputed tool.', gear:'handAuger',gearName:'Hand Auger',gearSource:'The county clerk signs out a separate public-works auger as a documented fee; the disputed tool is returned to its recorded owner.',coins:3,knowledge:'A tool’s location is evidence about a claim, not proof of who owns it.', combat:{enemy:'claim-jumpers',winChance:.52,damageOnLoss:5,winText:'The claim-jumpers back off when both crews stand together. The clerk records their threat and keeps the tool in custody.',lossText:'You are struck while holding the line; the workers withdraw to firm ground and the claim clerk is called.'} },
  { id:'the-flooded-chest', title:'The Flooded Chest', subtitle:'A river guide knows the ford has shifted but not what the silt hides.', hook:'A river guide chooses whether to recover a family’s sealed chest or mark a newly shifted ford.', role:'river guide assistant', activity:'rescue/care', setting:'river ford and ferry landing', risk:'HIGH', startTitle:'The Ford Moved Overnight', start:'Guide Tal Venn is helping a family retrieve a chest from their own washed-out landing. A Collapsible Water Pail, Sounding Rod, and rope are available; the brown water has covered the old depth marks.', kit:[{id:'rod',label:'Probe from the upstream bank with the Sounding Rod',consequence:'The rod finds a firm shelf upstream and silt near the old landing; it does not establish the channel’s full depth.'},{id:'pail',label:'Fill the Water Pail to compare the current’s pull',consequence:'The pail shows the current is stronger than yesterday, but the reading is only a warning, not a measure of the ford.'},{id:'rope',label:'Set a rope boundary and keep everyone on the bank',consequence:'The line keeps the family from stepping toward the chest before a safe route is known.'}], turnTitle:'The Chest Is Not the Only Loss', turn:'A child points to the chest while an adult searches for a dog’s collar lost in the same wash. The water continues to rise against the bank.', responses:[{id:'wait',label:'Wait for the water to fall before any recovery',consequence:'The family agrees; the chest and collar remain in place until a safer level.'},{id:'mark',label:'Mark the firm approach and retrieve the collar only',consequence:'The collar is reached from dry ground with the rod’s help; the chest stays beyond the uncertain channel.'},{id:'guide',label:'Ask the family to choose between waiting and risking the chest',consequence:'They choose to wait, understanding that the current changed after the storm.'}], settlement:'The family’s ferry keeper offers a spare Collapsible Water Pail from the landing stores as thanks; the family keeps its recovered property.', gear:'collapsibleWaterPail',gearName:'Collapsible Water Pail',gearSource:'The ferry keeper transfers a spare pail owned by the landing, not the family’s chest or equipment.',coins:2,knowledge:'Recent water marks and old depth marks answer different questions; compare them before entering a changed current.',combat:{enemy:'river thieves',winChance:.48,damageOnLoss:5,winText:'The thieves leave when the family calls from the ferry. The chest remains with its owners, and the crossing is closed.',lossText:'You are hurt defending the bank; Tal gets the family behind the ferry shed and the thieves flee without the chest.'} },
  { id:'the-roofline', title:'The Roofline', subtitle:'A roof walker asks you to keep the ladder and the household safe.', hook:'A roof repair helper chooses whether to protect the climber, the household, or the tools when rain arrives.', role:'roofing assistant', activity:'labor/repair', setting:'farmhouse roof and yard', risk:'MODERATE', startTitle:'A Ladder in Fresh Rain', start:'Roofer Mina Bell is replacing a loose ridge shingle before a storm. The household has a weatherproof cloak, a rope, and a pack frame carrying slate. You must manage the ground work while Bell checks the roof.', kit:[{id:'rope',label:'Tie the ladder foot to the porch post',consequence:'The ladder is steadier, but the rope is no longer free to haul slate.'},{id:'cloak',label:'Cover the slate with the Weatherproof Cloak',consequence:'The slate stays dry; Bell still needs another person watching the ladder.'},{id:'frame',label:'Move the slate onto the Pack Frame',consequence:'The frame carries the awkward stack away from the drip line, but the ladder stays exposed.'}], turnTitle:'Water Finds the Loose Shingle', turn:'Rain begins while Bell is still on the roof. The loose shingle lifts at one edge; it is not safe to reach across the wet pitch.', responses:[{id:'descend',label:'Call Bell down before resetting the ladder',consequence:'Bell climbs down by the tied ladder and the repair waits for dry weather.'},{id:'cover',label:'Cover the exposed roof from the porch, not the slope',consequence:'A ground sheet shields the leak temporarily; the roof work is postponed.'},{id:'household',label:'Move the household’s bedding away from the drip',consequence:'The family’s belongings are protected while Bell secures the tools below.'}], settlement:'Bell releases a spare Pack Frame from his own kit as compensation for carrying slate and watching the ladder.', gear:'packFrame',gearName:'Pack Frame',gearSource:'Bell signs over his personally owned frame; the household keeps its cloak and the ladder rope returns to the roof kit.',coins:2,knowledge:'When rain changes a roof’s footing, stopping the climb can be the repair that prevents a fall.', lore:'Bell learned the trade on slate roofs that had to be stripped before every winter.' },
  { id:'the-blind-cut', title:'The Blind Cut', subtitle:'A scout wants a second opinion before following a trail through a rock cut.', hook:'A scout and assistant distinguish an ambush sign from a genuine trail before entering a blind cut.', role:'scout assistant', activity:'investigation/mystery', setting:'rock cut on a stage road', risk:'HIGH', startTitle:'A Trail That Turns Too Neatly', start:'Scout Cora Dane has found boot prints entering a narrow cut and none leaving it. Field Glasses, a Survey Chain, and a Signal Flag Set are available. The evidence suggests a staged trail, but does not prove anyone is waiting.', kit:[{id:'glasses',label:'Watch the far lip through Field Glasses',consequence:'A loose pebble rolls from behind the far lip; it could be a person or a settling stone.'},{id:'chain',label:'Measure the cut from the open side',consequence:'The chain shows a side ledge can be reached from the road above without entering the cut.'},{id:'flags',label:'Set a visible retreat signal before approaching',consequence:'The signal gives Dane a way to call you back if either traveler loses sight of the other.'}], turnTitle:'Someone Watches the Road', turn:'A wagon slows at the cut and then turns back. The driver says two strangers asked which road the scout would take; no one has seen a weapon.', responses:[{id:'warn',label:'Warn the wagon and take the upper ledge',consequence:'The wagon turns toward the staffed tollhouse while you inspect the cut from above.'},{id:'call',label:'Call into the cut and offer a chance to answer',consequence:'Two men leave by the far road without approaching; the trail had drawn attention but not a fight.'},{id:'withdraw',label:'Withdraw and report the suspicious questions',consequence:'Dane records the description at the next station and does not enter an unverified blind cut.'}], settlement:'Dane’s employer pays the agreed scout fee, and the station keeper transfers a spare Signal Flag Set as your field equipment.', gear:'signalFlagSet',gearName:'Signal Flag Set',gearSource:'The station keeper signs over a separate spare set from the public route kit after the scout’s report is filed.',coins:3,knowledge:'A staged trail is a warning to slow down, not proof of an ambush; establish a retreat signal before narrowing your options.',combat:{enemy:'road robbers',winChance:.45,damageOnLoss:6,winText:'The two robbers withdraw when Dane blocks the road and the wagon driver sounds the station whistle. The toll clerk takes their description.',lossText:'You are wounded in the cut; Dane gets the wagon away and the robbers escape before the toll patrol arrives.'} },
  { id:'the-old-pulley', title:'The Old Pulley', subtitle:'A retired mine rescuer asks for help testing an old lift before anyone rides it.', hook:'A retired rescuer tests an old mine pulley with a weighted bucket before lowering a person.', role:'mine rescue assistant', activity:'rescue/care', setting:'closed mine headframe', risk:'HIGH', startTitle:'No One Rides the First Test', start:'Retired rescuer Harlan Pike has been asked to recover a survey case from a closed mine platform. The Compact Block-and-Tackle, Iron Rope Clamp, and Sounding Rod are all available, but the cable has not been inspected.', kit:[{id:'tackle',label:'Rig the block-and-tackle for a small test load',consequence:'The pulley bears the bucket’s weight from a separate timber; it does not prove the mine cable can carry a person.'},{id:'clamp',label:'Secure the stationary line with the Rope Clamp',consequence:'The clamp stops the wet line slipping while Pike inspects the cable, but it is not a lift brake.'},{id:'rod',label:'Probe the platform edge before approaching it',consequence:'The rod finds a hollow section beside the platform; the case can be reached from the solid side.'}], turnTitle:'The Cable Sings Once', turn:'A weighted bucket descends a few feet and the cable gives a sharp metallic note. Pike stops the test. The case remains visible, and the entrance timber creaks in the wind.', responses:[{id:'stop',label:'Stop the lift and ask the mine owner for a new cable',consequence:'The case stays behind, but no one is suspended from a cable that has not passed inspection.'},{id:'reach',label:'Use the rod from solid ground to draw the case closer',consequence:'The case slides within reach without anyone riding the lift or standing on the hollow platform.'},{id:'shore',label:'Brace the headframe while Pike checks the cable',consequence:'The brace steadies the outer frame for inspection; Pike still refuses to lower a person.'}], settlement:'Pike gives you his personal spare Rope Clamp, explaining that it secures a line but never certifies a lift.', gear:'ironRopeClamp',gearName:'Iron Rope Clamp',gearSource:'Pike transfers his privately owned clamp after the mine owner takes responsibility for replacing the unsafe cable.',coins:3,knowledge:'A test load is not proof that a worn lift can carry a person; stop when a cable gives a new sound.', lore:'Pike once worked a rescue where the lift cable had been replaced after a freeze.' },
  { id:'the-rail-shed', title:'The Rail Shed at Noon', subtitle:'A railway troubleshooter and a traveling mechanic disagree about a seized gate.', hook:'Two railway specialists disagree whether a seized gate needs force or a measured adjustment.', role:'railway troubleshooter assistant', activity:'labor/repair', setting:'rural rail shed', risk:'MODERATE', startTitle:'A Gate That Will Not Lift', start:'Rail troubleshooter Edda Sorn says the gate hinge is seized; mechanic Pell says the counterweight has shifted. Your Pocket Toolkit, a Hand Auger, and a pry tool could each test a different part. The line is closed while you work.', kit:[{id:'toolkit',label:'Inspect the hinge with the Pocket Toolkit',consequence:'The hinge pin turns a fraction; the gate may be binding at the counterweight rather than rusted solid.'},{id:'auger',label:'Check the timber post with the Hand Auger',consequence:'A small test bore shows the post is sound, but says nothing about the counterweight.'},{id:'pry',label:'Ease the gate with the Folding Pry Tool',consequence:'The gate moves slightly and then stops; force would hide whether the weight is balanced.'}], turnTitle:'Both Experts Hear Something', turn:'Sorn hears a scrape above the gate; Pell finds fresh iron filings at the pulley. Neither clue alone proves the cause.', responses:[{id:'open',label:'Lower the counterweight and inspect the pulley',consequence:'A bent cotter pin comes into view; the team replaces it before reopening the gate.'},{id:'test',label:'Unhook the gate and test the counterweight separately',consequence:'The counterweight moves freely, confirming the pulley pin is the fault.'},{id:'defer',label:'Keep the line closed until the foreman arrives',consequence:'The foreman finds the same pin and approves a measured repair rather than a forceful lift.'}], settlement:'Pell pays the agreed repair fee; Sorn releases a spare Pocket Toolkit from her personal railway kit instead of adding more coin.', gear:'pocketToolkit',gearName:'Pocket Toolkit',gearSource:'Sorn transfers her own spare kit after the railway foreman signs off the repaired gate; the railway’s issued set stays on site.',coins:3,knowledge:'When a gate binds, separate the hinge, counterweight, and pulley tests instead of forcing the whole assembly.', lore:'The shed was built for a line that closed before the present station opened.' },
  { id:'the-wet-powder', title:'A Dry Place for the Powder', subtitle:'A blasting foreman asks you to move supplies before rain reaches the quarry.', hook:'A quarry assistant protects stored powder and workers when rain threatens a blasting shed.', role:'quarry assistant', activity:'labor/repair', setting:'quarry powder shed', risk:'SEVERE', startTitle:'The Roof Has Started to Leak', start:'Quarry foreman Lyle Voss has closed the powder shed and stopped all blasting. A waxed canvas sheet, a water pail, and a handcart are available. The leak is small, but the powder must not be handled carelessly.', kit:[{id:'sheet',label:'Cover the roof opening from outside the shed',consequence:'The canvas diverts rain away from the door; nobody enters or touches the stored powder.'},{id:'pail',label:'Catch roof water in the Collapsible Water Pail',consequence:'The pail catches the drip, buying time to move ordinary tools without approaching the powder.'},{id:'cart',label:'Move tools and workers beyond the marked boundary',consequence:'The handcart clears the shed approach; the powder remains isolated until the foreman’s inspection.'}], turnTitle:'A Second Leak Appears', turn:'Water appears along a roof seam nearer the boundary. Voss orders the shed kept closed. There is no fire, no blast, and no reason to improvise around powder.', responses:[{id:'evacuate',label:'Keep the boundary clear and call the licensed powder keeper',consequence:'The keeper inspects from the proper procedure and arranges a controlled transfer after the storm.'},{id:'cover',label:'Extend the canvas from the outer wall without entering',consequence:'The additional cover slows the leak, but the shed remains closed pending inspection.'},{id:'wait',label:'Wait outside the boundary until the rain passes',consequence:'The crew waits under a separate shelter; no one handles the powder during the leak.'}], settlement:'Voss pays the agreed three-coin shift and gives you a spare Water Pail from the quarry’s ordinary stores; it was never powder-room equipment.', gear:'collapsibleWaterPail',gearName:'Collapsible Water Pail',gearSource:'The foreman releases a separately inventoried pail from the wash station, with no access to or transfer of blasting material.',coins:3,knowledge:'Powder handling belongs to trained procedures; a small leak is a reason to isolate the shed, not improvise inside it.', combat:undefined },
  { id:'the-brush-line', title:'The Brush Line', subtitle:'A hunting guide has to move a family through thick growth without losing the trail.', hook:'A guide creates a marked route through dense brush after a storm hides the old path.', role:'hunting guide assistant', activity:'survival', setting:'woodland edge and farm road', risk:'MODERATE', startTitle:'A Path Gone Green', start:'Guide Rena Fox is escorting two farmhands back from a boundary fence. The Folding Brush Saw, Trail Marker, and Weatherproof Cloak are available; rain has pushed new growth across the path.', kit:[{id:'saw',label:'Cut a narrow passage with the Folding Brush Saw',consequence:'The saw opens a person-wide route but leaves the thorn hedge intact.'},{id:'marker',label:'Mark the known turns before entering the brush',consequence:'The markers preserve the return route, though the group must still move through the growth.'},{id:'cloak',label:'Use the cloak as a shield against wet branches',consequence:'The cloak protects one traveler from the wet hedge, but the whole group still needs a route.'}], turnTitle:'The Fence Is Not the Boundary', turn:'A broken fence rail lies beyond the brush. One farmhand says it marks the property edge; Fox recognizes an older line of stones further uphill.', responses:[{id:'stone',label:'Find and compare the old stones before cutting farther',consequence:'The old stones show the fence was moved years ago; the group stays on the public side.'},{id:'ask',label:'Ask the farmhands which route they are authorized to use',consequence:'They choose the public cart road and leave the boundary question to the owner.'},{id:'mark',label:'Mark the current position and turn back',consequence:'The group retraces the marked route without crossing the uncertain fence line.'}], settlement:'Fox offers you her own spare Folding Brush Saw; she has a second one in the guide’s chest and will not need both on the return.', gear:'foldingBrushSaw',gearName:'Folding Brush Saw',gearSource:'Fox signs over her personally owned spare saw, not the landowner’s fence tools.',coins:2,knowledge:'A fence line and a property boundary need not be the same; check old markers before cutting a new route.',lore:'Fox learned the old stone line from a farmer who remembered the fence being moved.' },
  { id:'the-missing-brace', title:'The Missing Brace', subtitle:'A bridge inspector has found a gap in the inventory and a crowd waiting to cross.', hook:'A bridge inspection crew must keep a crowd off a span while locating a missing brace.', role:'bridge inspector assistant', activity:'rescue/care', setting:'county bridge approach', risk:'HIGH', startTitle:'The Span Stays Closed', start:'Inspector Arlen Voss has found one brace missing from the tool inventory. A Survey Chain, Signal Flags, and a Bridgewright’s Hammer are available. The bridge is closed, but a market crowd is gathering at the far end.', kit:[{id:'chain',label:'Measure the brace position from the bank',consequence:'The chain locates the missing brace socket without anyone stepping onto the closed span.'},{id:'flags',label:'Set the Signal Flags at both approaches',consequence:'The flags make the closure visible from the road bend, though a person must remain at each end.'},{id:'hammer',label:'Inspect the sound braces with the Bridgewright’s Hammer',consequence:'A careful tap reveals one other brace has a hollow note; replacing one part may not be enough.'}], turnTitle:'The Crowd Has Its Own Pressure', turn:'A cart driver starts moving a barrier to save time. No one is on the bridge, but the nearest crowd cannot see the inspector’s hand signal.', responses:[{id:'signal',label:'Use the agreed flags and ask the crowd to wait',consequence:'The far-end attendant repeats the pattern and the cart stops before the approach.'},{id:'route',label:'Open the longer road and escort people to it',consequence:'The crowd takes the detour; the bridge remains closed while the inspection continues.'},{id:'call',label:'Use the whistle to reach the far attendant',consequence:'The whistle carries over the road and the barrier is restored before any cart reaches the span.'}], settlement:'The county inspector transfers a spare Signal Flag Set from his personal survey kit as thanks for keeping the approaches clear.', gear:'signalFlagSet',gearName:'Signal Flag Set',gearSource:'Voss records the transfer of his personally owned spare flags; county closure flags remain with the bridge crew.',coins:3,knowledge:'A closure is only useful if both approaches can see or hear it; establish the communication plan before inspection.',lore:'The bridge’s braces were numbered after an earlier repair that found two missing pieces.' },
  { id:'the-wrong-cache', title:'The Wrong Cache', subtitle:'A ruin-seeker thinks a sealed case is his, but its markings disagree.', hook:'A ruins specialist asks an assistant to verify a case before opening it or claiming its contents.', role:'ruin-delver assistant', activity:'moral prioritization', setting:'stone cellar beneath an old way station', risk:'MODERATE', startTitle:'A Seal Not on the Map', start:'Delver Sima Rell has found a sealed case under a collapsed shelf. Her Field Glasses, Folding Pry Tool, and survey notes offer different ways to inspect it. The case bears a railway seal absent from her map.', kit:[{id:'glasses',label:'Read the seal with Field Glasses from a safe distance',consequence:'The distant mark is a railway inventory number, but the final digit is obscured by grime.'},{id:'pry',label:'Use the Folding Pry Tool to lift the broken shelf, not the case',consequence:'The shelf moves without breaking the seal; a second painted mark appears underneath.'},{id:'notes',label:'Compare the case position with the survey notes',consequence:'The notes place the cellar near the old way station’s freight wall, not in the ruin’s storeroom.'}], turnTitle:'Ownership Changes the Job', turn:'A station clerk confirms the number belongs to a sealed freight consignment. The case can be returned intact; opening it would destroy the owner’s seal.', responses:[{id:'return',label:'Carry the case to the clerk unopened',consequence:'The clerk signs the receipt and identifies the missing freight office that reported it years ago.'},{id:'wait',label:'Leave it in place until the clerk brings a witness',consequence:'Rell marks the location and asks the landowner to keep the cellar closed.'},{id:'document',label:'Record the seal and let the clerk arrange recovery',consequence:'The case stays sealed while the proper owner sends a recovery crew.'}], settlement:'Rell offers her own Folding Pry Tool as thanks for preserving the seal; she keeps the ruin’s equipment and survey notes.', gear:'foldingPryTool',gearName:'Folding Pry Tool',gearSource:'Rell transfers a separately owned duplicate after the clerk takes custody of the freight case.',coins:2,knowledge:'An object found in a ruin may still belong to a later institution; identify marks before opening or keeping it.',lore:'The way station freight wall was buried when the newer road was cut.' },
  { id:'the-rough-water-watch', title:'The Rough-Water Watch', subtitle:'A river guide sends you to watch a landing while she checks a mooring.', hook:'A river guide and support hand protect a ferry landing when a snag shifts in the current.', role:'river guide support hand', activity:'rescue/care', setting:'river ferry landing', risk:'HIGH', startTitle:'A Mooring Under Strain', start:'Guide Amos Bell is checking a ferry mooring after a sudden current change. From the bank you have Field Glasses, a Signal Flag Set, and a spare line. A skiff with two passengers is approaching the landing.', kit:[{id:'glasses',label:'Watch the upstream snag with Field Glasses',consequence:'The glasses show the snag moving but cannot tell whether the mooring will hold.'},{id:'flags',label:'Set the red flag to warn the approaching skiff',consequence:'The signal is visible from the open water, if the passengers are looking toward the landing.'},{id:'line',label:'Keep a spare line ready on the bank',consequence:'The line is available for a controlled tie-off, but it should not be thrown until the skiff is close enough.'}], turnTitle:'A Landing Can Be Closed', turn:'A branch catches the ferry line. Bell calls for the skiff to hold off; its passengers are close enough to hear but the current is pushing them sideways.', responses:[{id:'flag',label:'Repeat the agreed stop signal from the landing',consequence:'The passengers turn into the slower water and wait beyond the snag.'},{id:'line',label:'Secure the spare line to the bank before the skiff arrives',consequence:'Bell uses the shore line only after the skiff reaches the safe eddy.'},{id:'tow',label:'Guide the skiff toward the sheltered bend',consequence:'The skiff reaches the sheltered bend and waits for the ferry line to be cleared.'}], settlement:'Bell gives you his personally owned Field Glasses, a spare pair he uses for reading the current from shore.', gear:'fieldGlasses',gearName:'Field Glasses',gearSource:'Bell signs over his spare glasses after the passengers are safe; they are not the ferry’s operating equipment.',coins:2,knowledge:'A moving snag can change a landing faster than old marks show; close the crossing before trying to save a schedule.',combat:{enemy:'landing raiders',winChance:.5,damageOnLoss:4,winText:'The raiders abandon the bank when Bell rings the ferry bell and the passengers call from the eddy. The ferry crew secures its own line.',lossText:'You are struck while protecting the approach; Bell moves the passengers away and the raiders leave when the village answers the bell.'} },
  { id:'the-ash-frame', title:'The Ash Frame', subtitle:'A retired packer asks for help deciding what should travel and what should wait.', hook:'A retired expedition packer teaches load distribution during a journey with too few animals.', role:'expedition assistant', activity:'survival', setting:'foothill wagon road', risk:'LOW', startTitle:'Two Animals, Three Loads', start:'Retired packer Leda Orr has a Pack Frame, Freightman’s Strap, and canvas cover. A sudden change in road grade means the team cannot carry all three crates at once.', kit:[{id:'frame',label:'Put the heaviest crate on the Pack Frame',consequence:'The load sits close to the shoulders, but its weight must be shared with a second carrier.'},{id:'strap',label:'Bind the awkward crate with the Freightman’s Strap',consequence:'The strap holds the crate together; it does not reduce its weight.'},{id:'cover',label:'Cover the fragile crate before moving it',consequence:'The canvas protects the contents from rain while the team decides which load can wait.'}], turnTitle:'A Crate Is Not the Whole Expedition', turn:'One crate holds seed samples promised to a school. Another holds spare fittings for the wagon. The road rises sharply and one mule is tiring.', responses:[{id:'samples',label:'Carry the seed samples and leave the fittings with the wagon',consequence:'The samples reach the school intact; Orr arranges to retrieve the fittings with another team.'},{id:'rest',label:'Rest the mule and split the load into two trips',consequence:'The team loses half a day, but no animal is pushed beyond its strength.'},{id:'repair',label:'Use a spare fitting to stabilize the wagon for a shorter trip',consequence:'The wagon reaches the school with the samples and a temporary repair that Orr will replace later.'}], settlement:'Orr’s Pack Frame has been hers since her first expedition. She has retired and gives it to you with her written notes on fitting it.', gear:'packFrame',gearName:'Pack Frame',gearSource:'Orr passes on her personally owned frame as a retirement gift, after the school receives its samples.',coins:2,knowledge:'Load balance is a living choice: reduce weight, redistribute it, or plan another trip instead of forcing an animal onward.',lore:'Orr’s ash frame has initials from three different expeditions carved into the crossbar.' },
  { id:'the-storm-marker', title:'The Storm Marker', subtitle:'A trail crew asks for help restoring signs after a night of hard rain.', hook:'A trail crew tests whether old markers still lead safely through a washed-out fork.', role:'trail crew assistant', activity:'travel/exploration', setting:'woodland trail fork', risk:'MODERATE', startTitle:'A Marker Facing Uphill', start:'Trail keeper Mott has a Survey Chain, Folding Trail Marker, and Field Glasses. One marker now points uphill toward a fresh wash, while the old footpath continues beside the creek.', kit:[{id:'chain',label:'Measure the creek path from the last fixed post',consequence:'The chain confirms the old path’s distance, but not whether the creek bank has stayed firm.'},{id:'marker',label:'Place a temporary marker at the safe fork',consequence:'The temporary marker warns travelers not to follow the old arrow blindly.'},{id:'glasses',label:'Look for the next marker through Field Glasses',consequence:'The distant marker is visible beyond the bend, but the storm may have moved its post.'}], turnTitle:'A Missing Footbridge', turn:'The next footbridge has washed away. A hiker is waiting on the far side, unhurt, while the signed detour crosses a higher ridge.', responses:[{id:'detour',label:'Show the hiker the marked ridge detour',consequence:'The hiker takes the longer route while Mott closes the creek path.'},{id:'call',label:'Call across and arrange a meeting at the ridge',consequence:'The hiker confirms they can reach the ridge without crossing the damaged bank.'},{id:'wait',label:'Keep the trail closed until a second crew arrives',consequence:'The hiker stays on firm ground and the crew posts a closure from both ends.'}], settlement:'Mott releases a spare Folding Trail Marker from the crew’s duplicate stock as payment for resetting the route.', gear:'foldingTrailMarker',gearName:'Folding Trail Marker',gearSource:'The trail keeper documents the duplicate marker’s transfer; the active route signs stay with the public crew.',coins:2,knowledge:'After a storm, a familiar sign may point to a changed path; verify the next marker before following it.',lore:'This trail’s original footbridge was built by a volunteer crew after the road washed out.' },
  { id:'the-lamp-in-the-cut', title:'The Lamp in the Cut', subtitle:'A cave scout’s lamp keeps failing, but the problem is not the lamp.', hook:'A cave scout and assistant diagnose a failing lamp while a partner waits at a safe entrance.', role:'cave scout assistant', activity:'travel/exploration', setting:'limestone cut and sheltered entrance', risk:'HIGH', startTitle:'A Flame That Leans', start:'Scout Pella Roe has a Roadman’s Lantern, a Windproof Match Case, and a folding mirror. In the entrance cut, the lantern flame leans only when the bearer turns toward a narrow fissure.', kit:[{id:'mirror',label:'Use the mirror to see the lower air opening',consequence:'The mirror shows dust drawing inward at the lower vent; the lamp’s wick is steady.'},{id:'matches',label:'Protect the spare matches and test the shutter outside',consequence:'The matches stay dry, but the flame still leans near the fissure.'},{id:'lantern',label:'Turn the lantern and observe the flame from the entrance',consequence:'The flame steadies when turned away from the fissure; airflow is the likely cause.'}], turnTitle:'The Scout Hears a Second Draft', turn:'A second current comes from behind a loose stone. Roe asks you not to move it until the partner at the entrance has a clear retreat signal.', responses:[{id:'signal',label:'Signal the partner before inspecting the stone',consequence:'The partner answers from the entrance and keeps the return path clear.'},{id:'leave',label:'Mark the draft and leave the stone undisturbed',consequence:'Roe records the airflow and postpones the inspection until a second scout arrives.'},{id:'inspect',label:'Inspect from the entrance with the mirror',consequence:'You see a narrow air gap behind the stone without putting a hand into it.'}], settlement:'Roe gives you a spare Folding Card Mirror from her personal kit; it has helped her inspect narrow fittings and dark corners.', gear:'foldingCardMirror',gearName:'Folding Card Mirror',gearSource:'Roe transfers her own spare mirror after the group returns to the entrance; the cave remains marked for later inspection.',coins:2,knowledge:'A flame that changes with orientation can reveal airflow, but it does not prove what lies beyond the draft.',lore:'Roe learned the mirror trick from a tinsmith who inspected stove flues.' },
  { id:'the-second-gunhand', title:'The Second Gunhand', subtitle:'A hired guard asks for help protecting a payroll wagon without starting a fight.', hook:'A guard and support hand protect a payroll wagon after a staged obstruction appears on the road.', role:'temporary guard support', activity:'combat/defense', setting:'wooded stage road', risk:'HIGH', startTitle:'A Cord Across the Road', start:'Guard Hester Vane is escorting a payroll wagon under contract. A cut rope lies across the road, and the wagon driver sees movement near the tree line. Vane has a Conductor’s Whistle, a Signal Flag Set, and a spare rope; the contract forbids opening fire without a clear threat.', kit:[{id:'whistle',label:'Use the whistle to halt the wagon at distance',consequence:'The wagon stops before the obstruction; the sound tells the hidden men they have been seen.'},{id:'flags',label:'Signal the driver to turn toward the toll station',consequence:'The wagon begins backing toward the staffed road while Vane watches the tree line.'},{id:'rope',label:'Keep the spare rope to clear the road from cover',consequence:'The rope lets you move the obstruction without stepping into the open, but the wagon stays halted.'}], turnTitle:'A Threat Steps into View', turn:'Two armed robbers leave the trees and order the driver down. Their weapons are visible; they have not fired. The toll station is within shouting distance.', responses:[{id:'call',label:'Call for the toll patrol and keep the wagon behind cover',consequence:'The patrol answers from the station and the robbers withdraw before the wagon moves.'},{id:'negotiate',label:'Offer the robbers a clear retreat if they leave the road',consequence:'They take the retreat and leave the payroll untouched; Vane records their direction.'},{id:'fight',label:'Stand with Vane and fight the road robbers',consequence:'Vane holds the wagon’s near side while you keep the driver behind the wheel shield.'}], settlement:'The employer pays your agreed guard fee and lets you keep the spare rope Vane bought for the contract.', gear:'travelRope',gearName:'Travel Rope',gearSource:'The employer signs the separately purchased spare rope over as part of your contracted support pay; the escort’s working line remains with Vane.',coins:3,knowledge:'An armed threat is real, but a nearby patrol and a clear withdrawal route may prevent a fight.',combat:{enemy:'payroll robbers',winChance:.48,damageOnLoss:6,winText:'The robbers retreat when the patrol arrives; the wagon remains behind cover until the road is cleared.',lossText:'You are badly hurt in the exchange; Vane gets the driver behind cover and the patrol arrives as the robbers flee.'} },
];

